\documentclass{article}
\usepackage{pgfplots}
\pagestyle{empty}
\usetikzlibrary{calc}
\begin{document}
\begin{tikzpicture}
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}

\begin{axis}
[
  axis lines=middle,
  tick label style={font=\footnotesize},
  label style={font=\small},
  tick style={draw=none},
  %grid=both,
  xmin=-1.75,
  xmax=7.75,
  ymin=-0.75,
  ymax=5.75,
xtick={\empty},
ytick={\empty},
%  minor xtick={-9,-7,...,9},
 % minor ytick={-9,-7,...,9},
  xlabel=$x$,
  ylabel=$y$,
xlabel style={right},
ylabel style={above},
axis line style = thick,
]  

\addplot[domain=4:9, samples=100, line width=0.75pt, smooth, samples=1000, color=deepskyblue, opacity=0.5, dashed] {4*2^(-x+4)};
\addplot[domain=-5:4, samples=100,line width=0.75pt, smooth, samples=1000, color=deepskyblue, opacity=0.5, dashed] {4*2^(x-4)};

\node[label={below, yshift=-3pt:{{\small $(4,1)$}}},circle,deepskyblue,fill, inner sep=1.5pt] at (axis cs:4,1) {};

\addplot[domain=4:9, samples=100, line width=1pt, smooth, samples=1000, color=deepskyblue] {1*2^(-x+4)};
\addplot[domain=-5:4, samples=100,line width=1pt, smooth, samples=1000, color=deepskyblue] {1*2^(x-4)};


\node[label={90, opacity=0.5:{{\small{$(4,4)$}}}},circle,fill, deepskyblue, inner sep=1.2pt, opacity=0.5] at (axis cs:4,4) {};

\draw[->, orangepeel, thick, shorten < = 1.5mm, shorten >= 1.5mm] (axis cs:4,4) -- (axis cs:4,1) node[pos=0.7, left=-1pt] {$\div\,4$};


\end{axis}
\end{tikzpicture}
\end{document}

